// ============================================================================
// PAGE TYPES - Complete Unified VAM Design + Phase 7 & 8
// ============================================================================

export type PageType =
  // Core
  | 'dashboard'
  | 'dashboard-classic'
  | 'accounts'
  | 'programs'
  | 'parties'
  | 'beneficiaries' 
  | 'transactions' 
  | 'physical-accounts'
  | 'statements'

  // Finance - List Views
  | 'receivables'
  | 'payables'
  | 'escrow' 
  | 'wallet' 

  // Finance - Create/Edit Views
  | 'receivables-create'
  | 'receivables-edit'
  | 'payables-create'
  | 'payables-edit'

  // BaaS Platform
  | 'baas-dashboard'
  | 'baas-partners'
  | 'baas-cards'
  | 'baas-cash'
  | 'baas-settlements'
  | 'baas-transactions'

  // Compliance
  | 'kycc'
  | 'viban'

  // Treasury - Core
  | 'ihb'
  | 'pooling'
  | 'notional-pooling'
  | 'sweeping'
  | 'simulator'
  | 'netting-enhanced'  // Phase 7 Enhanced Netting
  | 'hierarchy'
  | 'forecasting'

  // Treasury - Phase 7 (Shadow, Currency Mirror, Credit, Funds)
  | 'shadow-accounts'
  | 'multi-bank-liquidity'
  | 'currency-mirrors'
  | 'credit-limits'
  | 'funds-check'
  | 'balance-aggregation'
  | 'fx-rates'
  | 'entity-balance-tree'

  // Unified VAM Design - Legal Entity & Account Attachments
  | 'legal-entities'
  | 'account-attachments'

  // Credit Management
  | 'credit-agreements'
  | 'credit-facilities'
  | 'interest-config'
  | 'interest-accruals'

  // Settlement & Exception (Phase 3)
  | 'settlement-vas'
  | 'exceptions'

  // Phase 8: Intercompany Management
  | 'intercompany'
  | 'intercompany-pobo'
  | 'intercompany-cobo'
  | 'intercompany-settlement'

  // E-commerce
  | 'ecommerce-dashboard'
  | 'ecommerce-collections'
  | 'merchant-onboarding'
  | 'seller-collections'
  | 'hierarchy-operations'
  | 'operation-history'

  // Admin
  | 'sync-admin'
  | 'integrations'
  | 'tax-charges'
  | 'settings'

  // ISO 20022 Payments
  | 'iso20022'

  // Fund Transfers
  | 'transfers';

// ============================================================================
// NAVIGATION CONTEXT
// ============================================================================

export interface NavigationContextType {
  currentPage: PageType;
  navigate: (page: PageType, params?: Record<string, string>) => void;
  goBack: () => void;
  params: Record<string, string>;
  selectedProgramId: string | null;
}

const NavigationContext = createContext<NavigationContextType | null>(null);

export const useNavigation = () => {
  const context = useContext(NavigationContext);
  if (!context) {
    throw new Error('useNavigation must be used within NavigationProvider');
  }
  return context;
};

