// ============================================================================
// HIERARCHY LEVEL CONFIGURATION MODAL
// Path: src/components/HierarchyLevelConfigModal.tsx
// Purpose: Allow corporate users to configure hierarchy levels and allowed values
// ============================================================================

import React, { useState, useEffect } from 'react';
import {
  Settings, Save, X, Plus, Trash2, GripVertical, ChevronDown, ChevronUp,
  AlertCircle, CheckCircle, Info, Layers, Tag, List, Edit2, RefreshCw,
} from 'lucide-react';
import { Modal } from './ui/enhanced';
import { Card, Badge, Button, Input, Select } from './ui';
import { cn } from '../utils';

// ============================================================================
// TYPES
// ============================================================================

export interface HierarchyLevelConfig {
  id?: string;
  programId?: string;
  levelNumber: number;
  levelName: string;
  dimensionType: string;
  isRequired?: boolean;
  allowedValues?: string[];
  description?: string;
}

interface HierarchyLevelConfigModalProps {
  isOpen: boolean;
  onClose: () => void;
  programId: string;
  programName?: string;
  programType?: string;
  initialLevels?: HierarchyLevelConfig[];
  onSave: (levels: HierarchyLevelConfig[]) => Promise<void>;
  /** If true, shows a warning that modifying levels may affect existing hierarchy nodes */
  hasExistingNodes?: boolean;
  /** Number of existing hierarchy nodes (for display in warning) */
  existingNodeCount?: number;
  /** Program's hierarchy level cap (Program.maxHierarchyDepth). The editor
   *  honors this — hierarchy depth is extensible by design, not fixed at 7. */
  maxDepth?: number;
}

/** Backend default for Program.maxHierarchyDepth. */
const DEFAULT_MAX_DEPTH = 20;

// ============================================================================
// DIMENSION TYPES - Available options for each level
// ============================================================================

const DIMENSION_TYPES = [
  { value: 'CURRENCY', label: 'Currency', description: 'Currency code (AED, USD, EUR)' },
  { value: 'REGION', label: 'Region', description: 'Geographic region' },
  { value: 'COUNTRY', label: 'Country', description: 'Country code' },
  { value: 'STATE', label: 'State/Province', description: 'State or province' },
  { value: 'CITY', label: 'City', description: 'City name' },
  { value: 'ENTITY', label: 'Legal Entity', description: 'Legal entity code' },
  { value: 'DEPARTMENT', label: 'Department', description: 'Department or division' },
  { value: 'COST_CENTER', label: 'Cost Center', description: 'Cost center code' },
  { value: 'ACCOUNT_TYPE', label: 'Account Type', description: 'Account classification' },
  { value: 'CHANNEL', label: 'Channel', description: 'Collection/payment channel' },
  { value: 'PLATFORM', label: 'Platform', description: 'Platform or gateway' },
  { value: 'SEGMENT', label: 'Segment', description: 'Customer segment' },
  { value: 'CUSTOMER', label: 'Customer', description: 'Customer identifier' },
  { value: 'MERCHANT', label: 'Merchant', description: 'Merchant identifier' },
  { value: 'PARTNER', label: 'Partner', description: 'Partner identifier' },
  { value: 'TIER', label: 'Tier', description: 'Customer tier level' },
  { value: 'BUDGET_OWNER', label: 'Budget Owner', description: 'Budget owner' },
  { value: 'VIRTUAL_ACCOUNT', label: 'Virtual Account', description: 'Leaf level VA' },
];

// Common allowed values for different dimension types
const SUGGESTED_VALUES: Record<string, string[]> = {
  CURRENCY: ['AED', 'USD', 'EUR', 'GBP', 'SAR', 'INR', 'CNY', 'JPY'],
  REGION: ['NORTH', 'SOUTH', 'EAST', 'WEST', 'MENA', 'APAC', 'EMEA', 'AMERICAS'],
  COUNTRY: ['AE', 'SA', 'US', 'UK', 'IN', 'SG', 'DE', 'FR'],
  SEGMENT: ['CORPORATE', 'SME', 'RETAIL', 'GOVERNMENT', 'ENTERPRISE'],
  CHANNEL: ['INVOICE', 'ECOMMERCE', 'POS', 'DIRECT', 'STANDING_ORDER', 'QR_CODE'],
  ACCOUNT_TYPE: ['PAYABLES', 'RECEIVABLES', 'TAXES', 'PAYROLL', 'CAPEX', 'OPEX', 'INTERCOMPANY'],
  TIER: ['PLATINUM', 'GOLD', 'SILVER', 'BRONZE', 'STANDARD'],
};

// ============================================================================
// LEVEL EDITOR COMPONENT
// ============================================================================

interface LevelEditorProps {
  level: HierarchyLevelConfig;
  onChange: (level: HierarchyLevelConfig) => void;
  isExpanded: boolean;
  onToggleExpand: () => void;
  canDelete: boolean;
  onDelete: () => void;
}

const LevelEditor: React.FC<LevelEditorProps> = ({
  level,
  onChange,
  isExpanded,
  onToggleExpand,
  canDelete,
  onDelete,
}) => {
  const [newValue, setNewValue] = useState('');

  const handleAddValue = () => {
    if (!newValue.trim()) return;
    const currentValues = level.allowedValues || [];
    if (!currentValues.includes(newValue.trim().toUpperCase())) {
      onChange({
        ...level,
        allowedValues: [...currentValues, newValue.trim().toUpperCase()],
      });
    }
    setNewValue('');
  };

  const handleRemoveValue = (value: string) => {
    onChange({
      ...level,
      allowedValues: (level.allowedValues || []).filter(v => v !== value),
    });
  };

  const handleApplySuggested = () => {
    const suggested = SUGGESTED_VALUES[level.dimensionType];
    if (suggested) {
      onChange({ ...level, allowedValues: suggested });
    }
  };

  const dimensionInfo = DIMENSION_TYPES.find(d => d.value === level.dimensionType);
  const hasSuggestedValues = SUGGESTED_VALUES[level.dimensionType];

  return (
    <div className={cn(
      'border rounded-lg transition-all',
      isExpanded ? 'border-primary-300 bg-primary-50/50' : 'border-neutral-200 hover:border-neutral-300 dark:border-primary-800'
    )}>
      {/* Header */}
      <div
        className="flex items-center gap-3 p-3 cursor-pointer"
        onClick={onToggleExpand}
      >
        <div className="flex items-center gap-2 flex-shrink-0">
          <GripVertical className="w-4 h-4 text-neutral-400" />
          <span className="w-7 h-7 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center text-sm font-semibold dark:bg-primary-700 dark:text-neutral-200">
            {level.levelNumber}
          </span>
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-medium text-primary-900 dark:text-neutral-50">{level.levelName}</span>
            <Badge variant="neutral" size="sm">{level.dimensionType}</Badge>
            {level.isRequired && <Badge variant="success" size="sm">Required</Badge>}
            {(level.allowedValues?.length || 0) > 0 && (
              <Badge variant="info" size="sm">{level.allowedValues?.length} values</Badge>
            )}
          </div>
          {level.description && (
            <p className="text-xs text-neutral-500 mt-0.5 truncate dark:text-neutral-400">{level.description}</p>
          )}
        </div>

        <div className="flex items-center gap-2">
          {canDelete && (
            <button
              onClick={(e) => { e.stopPropagation(); onDelete(); }}
              className="p-1 text-neutral-400 hover:text-error-600 transition-colors"
              title="Remove level"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          )}
          {isExpanded ? <ChevronUp className="w-4 h-4 text-neutral-400" /> : <ChevronDown className="w-4 h-4 text-neutral-400" />}
        </div>
      </div>

      {/* Expanded Content */}
      {isExpanded && (
        <div className="px-4 pb-4 pt-2 border-t border-neutral-200 space-y-4 dark:border-primary-800">
          {/* Level Name & Dimension Type */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Input
                label="Level Name"
                inputSize="sm"
                value={level.levelName}
                onChange={(e) => onChange({ ...level, levelName: e.target.value })}
                placeholder="e.g., Region, Department"
              />
            </div>
            <div>
              <Select
                label="Dimension Type"
                selectSize="sm"
                value={level.dimensionType}
                onChange={(e) => onChange({ ...level, dimensionType: e.target.value, allowedValues: [] })}
                options={DIMENSION_TYPES.map((d) => ({
                  value: d.value,
                  label: d.label,
                }))}
              />
            </div>
          </div>

          {/* Description */}
          <div>
            <Input
              label="Description"
              inputSize="sm"
              value={level.description || ''}
              onChange={(e) => onChange({ ...level, description: e.target.value })}
              placeholder="What this level represents..."
            />
          </div>

          {/* Required Toggle */}
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              className="w-4 h-4 rounded border-neutral-300 dark:border-primary-700"
              checked={level.isRequired || false}
              onChange={(e) => onChange({ ...level, isRequired: e.target.checked })}
            />
            <span className="text-sm text-neutral-700 dark:text-neutral-200">This level is required</span>
          </label>

          {/* Allowed Values */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="block text-xs font-medium text-neutral-600 dark:text-neutral-300">
                Allowed Values
                <span className="font-normal text-neutral-400 ml-1">(leave empty for any value)</span>
              </label>
              {hasSuggestedValues && (
                <button
                  onClick={handleApplySuggested}
                  className="text-xs text-primary-600 hover:text-primary-700 flex items-center gap-1 dark:text-primary-200"
                >
                  <RefreshCw className="w-3 h-3" />
                  Apply suggested
                </button>
              )}
            </div>

            {/* Current Values */}
            <div className="flex flex-wrap gap-2 mb-2 min-h-[32px]">
              {(level.allowedValues || []).map((value) => (
                <span
                  key={value}
                  className="inline-flex items-center gap-1 px-2 py-1 bg-white border border-neutral-200 rounded text-sm dark:bg-primary-900 dark:border-primary-800"
                >
                  {value}
                  <button
                    onClick={() => handleRemoveValue(value)}
                    className="text-neutral-400 hover:text-error-600"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              ))}
              {(level.allowedValues?.length || 0) === 0 && (
                <span className="text-xs text-neutral-400 italic">No restrictions - any value allowed</span>
              )}
            </div>

            {/* Add New Value */}
            <div className="flex gap-2">
              <input
                type="text"
                className="flex-1 px-3 py-2 border border-neutral-300 rounded-lg text-sm dark:border-primary-700"
                placeholder="Add allowed value..."
                value={newValue}
                onChange={(e) => setNewValue(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAddValue()}
              />
              <Button size="sm" variant="outline" onClick={handleAddValue}>
                <Plus className="w-4 h-4" />
              </Button>
            </div>

            {/* Suggested Values Quick Add */}
            {hasSuggestedValues && (
              <div className="mt-2">
                <p className="text-xs text-neutral-500 mb-1 dark:text-neutral-400">Quick add:</p>
                <div className="flex flex-wrap gap-1">
                  {SUGGESTED_VALUES[level.dimensionType]
                    .filter(v => !(level.allowedValues || []).includes(v))
                    .slice(0, 6)
                    .map(value => (
                      <button
                        key={value}
                        onClick={() => onChange({
                          ...level,
                          allowedValues: [...(level.allowedValues || []), value],
                        })}
                        className="px-2 py-0.5 text-xs bg-neutral-100 hover:bg-primary-100 rounded transition-colors dark:bg-primary-800"
                      >
                        + {value}
                      </button>
                    ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// ============================================================================
// MAIN MODAL COMPONENT
// ============================================================================

export const HierarchyLevelConfigModal: React.FC<HierarchyLevelConfigModalProps> = ({
  isOpen,
  onClose,
  programId,
  programName,
  programType,
  initialLevels,
  onSave,
  maxDepth,
  hasExistingNodes = false,
  existingNodeCount = 0,
}) => {
  const effectiveMaxDepth = maxDepth ?? DEFAULT_MAX_DEPTH;
  const [levels, setLevels] = useState<HierarchyLevelConfig[]>([]);
  const [expandedLevel, setExpandedLevel] = useState<number | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Initialize levels
  useEffect(() => {
    if (initialLevels && initialLevels.length > 0) {
      setLevels(initialLevels);
    } else {
      // Default 7-level structure
      setLevels([
        { levelNumber: 1, levelName: 'Currency', dimensionType: 'CURRENCY', isRequired: true },
        { levelNumber: 2, levelName: 'Region', dimensionType: 'REGION', isRequired: true },
        { levelNumber: 3, levelName: 'Country', dimensionType: 'COUNTRY', isRequired: true },
        { levelNumber: 4, levelName: 'Entity', dimensionType: 'ENTITY', isRequired: true },
        { levelNumber: 5, levelName: 'Department', dimensionType: 'DEPARTMENT', isRequired: false },
        { levelNumber: 6, levelName: 'Account Type', dimensionType: 'ACCOUNT_TYPE', isRequired: true },
        { levelNumber: 7, levelName: 'Virtual Account', dimensionType: 'VIRTUAL_ACCOUNT', isRequired: true },
      ]);
    }
    setHasChanges(false);
  }, [initialLevels, isOpen]);

  const handleLevelChange = (index: number, updatedLevel: HierarchyLevelConfig) => {
    const newLevels = [...levels];
    newLevels[index] = updatedLevel;
    setLevels(newLevels);
    setHasChanges(true);
  };

  const handleDeleteLevel = (index: number) => {
    if (levels.length <= 2) return; // Minimum 2 levels required
    const newLevels = levels.filter((_, i) => i !== index).map((l, i) => ({ ...l, levelNumber: i + 1 }));
    setLevels(newLevels);
    setHasChanges(true);
  };

  const handleAddLevel = () => {
    if (levels.length >= effectiveMaxDepth) return;
    const newLevel: HierarchyLevelConfig = {
      levelNumber: levels.length + 1,
      levelName: `Level ${levels.length + 1}`,
      dimensionType: 'ENTITY',
      isRequired: false,
    };
    setLevels([...levels, newLevel]);
    setExpandedLevel(levels.length);
    setHasChanges(true);
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await onSave(levels);
      setHasChanges(false);
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save configuration');
    } finally {
      setSaving(false);
    }
  };

  const handleClose = () => {
    if (hasChanges) {
      if (confirm('You have unsaved changes. Are you sure you want to close?')) {
        onClose();
      }
    } else {
      onClose();
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title={
        <div className="flex items-center gap-2">
          <Settings className="w-5 h-5 text-primary-600 dark:text-primary-200" />
          <span>Hierarchy Level Configuration</span>
        </div>
      }
      size="lg"
    >
      <div className="p-4 space-y-4">
        {/* Header Info */}
        <div className="bg-neutral-50 rounded-lg p-3 dark:bg-primary-950">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-primary-900 dark:text-neutral-50">{programName || 'Program'}</p>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">
                Configure the hierarchy levels and allowed values for virtual accounts
              </p>
            </div>
            {programType && <Badge variant="info">{programType}</Badge>}
          </div>
        </div>

        {/* Info Box */}
        <div className="bg-info-50 border border-info-200 rounded-lg p-3 flex gap-2 dark:bg-info-500/10 dark:border-info-500/30">
          <Info className="w-4 h-4 text-info-600 flex-shrink-0 mt-0.5 dark:text-info-300" />
          <div className="text-sm text-info-700 dark:text-info-300">
            <p className="font-medium">How Allowed Values Work</p>
            <ul className="mt-1 space-y-0.5 text-xs">
              <li>• Define what values are valid for each hierarchy level</li>
              <li>• When creating VAs, users can only select from these values</li>
              <li>• Leave empty to allow any value (free-form input)</li>
              <li>• Values are case-insensitive (stored uppercase)</li>
            </ul>
          </div>
        </div>

        {/* Warning: Existing Nodes */}
        {hasExistingNodes && (
          <div className="bg-warning-50 border border-warning-300 rounded-lg p-3 flex gap-2 dark:bg-warning-500/10">
            <AlertCircle className="w-4 h-4 text-warning-600 flex-shrink-0 mt-0.5 dark:text-warning-300" />
            <div className="text-sm text-warning-800 dark:text-warning-300">
              <p className="font-medium">Hierarchy Already Has Nodes</p>
              <p className="mt-1 text-xs text-warning-700 dark:text-warning-300">
                This program has {existingNodeCount > 0 ? `${existingNodeCount} existing hierarchy nodes` : 'existing hierarchy nodes'}.
                Modifying level configurations may cause inconsistencies with existing data.
                Changes to allowed values will only affect new nodes - existing nodes will retain their current values.
              </p>
              <p className="mt-1 text-xs text-warning-600 font-medium dark:text-warning-300">
                It is recommended to configure levels during program setup, before creating hierarchy nodes.
              </p>
            </div>
          </div>
        )}

        {/* Error Display */}
        {error && (
          <div className="bg-error-50 border border-error-200 rounded-lg p-3 flex gap-2 dark:bg-error-500/10 dark:border-error-500/30">
            <AlertCircle className="w-4 h-4 text-error-600 flex-shrink-0 dark:text-error-300" />
            <p className="text-sm text-error-700 dark:text-error-300">{error}</p>
          </div>
        )}

        {/* Level List */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-neutral-700 dark:text-neutral-200">
              Hierarchy Levels ({levels.length}/{effectiveMaxDepth})
            </h3>
            {levels.length < effectiveMaxDepth && (
              <Button size="sm" variant="outline" onClick={handleAddLevel}>
                <Plus className="w-4 h-4 mr-1" />
                Add Level
              </Button>
            )}
          </div>

          <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
            {levels.map((level, index) => (
              <LevelEditor
                key={level.levelNumber}
                level={level}
                onChange={(updated) => handleLevelChange(index, updated)}
                isExpanded={expandedLevel === index}
                onToggleExpand={() => setExpandedLevel(expandedLevel === index ? null : index)}
                canDelete={levels.length > 2 && index !== 0 && index !== levels.length - 1}
                onDelete={() => handleDeleteLevel(index)}
              />
            ))}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between pt-4 border-t">
          <div className="flex items-center gap-2 text-xs text-neutral-500 dark:text-neutral-400">
            {hasChanges ? (
              <>
                <AlertCircle className="w-3 h-3 text-warning-500" />
                <span className="text-warning-600 dark:text-warning-300">Unsaved changes</span>
              </>
            ) : (
              <>
                <CheckCircle className="w-3 h-3 text-success-500" />
                <span>All changes saved</span>
              </>
            )}
          </div>
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleClose}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !hasChanges}>
              {saving ? (
                <>
                  <RefreshCw className="w-4 h-4 mr-1 animate-spin" />
                  Saving...
                </>
              ) : (
                <>
                  <Save className="w-4 h-4 mr-1" />
                  Save Configuration
                </>
              )}
            </Button>
          </div>
        </div>
      </div>
    </Modal>
  );
};

export default HierarchyLevelConfigModal;

import React, { useState, useEffect } from 'react';
import {
  Search,
  Globe,
  Shield,
  Building2,
  ChevronRight,
  Loader2,
  Check,
  AlertCircle,
} from 'lucide-react';
import { Modal } from '../components/ui/enhanced';
import { cn } from '../utils';

// ============================================================================
// TYPES
// ============================================================================

interface Aspsp {
  aspspId: string;
  name: string;
  bic?: string;
  country: string;
  logoUrl?: string;
  supportedFeatures: string[];
  supportsAis: boolean;
  supportsPis: boolean;
  supportsCof: boolean;
}

interface OpenBankingSetupProps {
  isOpen: boolean;
  onClose: () => void;
  connectorCode: string;
  connectorName: string;
  onInitiateAuth: (aspspId: string, permissions: string[]) => Promise<{ authorizationUrl: string }>;
  onFetchAspsps: (country?: string, search?: string) => Promise<Aspsp[]>;
}

// ============================================================================
// COUNTRY CONFIG
// ============================================================================

const countries = [
  { code: 'GB', name: 'United Kingdom', flag: '🇬🇧' },
  { code: 'DE', name: 'Germany', flag: '🇩🇪' },
  { code: 'FR', name: 'France', flag: '🇫🇷' },
  { code: 'NL', name: 'Netherlands', flag: '🇳🇱' },
  { code: 'ES', name: 'Spain', flag: '🇪🇸' },
  { code: 'IT', name: 'Italy', flag: '🇮🇹' },
  { code: 'BE', name: 'Belgium', flag: '🇧🇪' },
  { code: 'AT', name: 'Austria', flag: '🇦🇹' },
  { code: 'CH', name: 'Switzerland', flag: '🇨🇭' },
  { code: 'PL', name: 'Poland', flag: '🇵🇱' },
  { code: 'SE', name: 'Sweden', flag: '🇸🇪' },
  { code: 'NO', name: 'Norway', flag: '🇳🇴' },
  { code: 'DK', name: 'Denmark', flag: '🇩🇰' },
  { code: 'FI', name: 'Finland', flag: '🇫🇮' },
  { code: 'IE', name: 'Ireland', flag: '🇮🇪' },
  { code: 'PT', name: 'Portugal', flag: '🇵🇹' },
];

const permissionOptions = [
  { id: 'AIS', label: 'Account Information', desc: 'View balances and transactions' },
  { id: 'PIS', label: 'Payment Initiation', desc: 'Initiate payments from accounts' },
  { id: 'COF', label: 'Confirmation of Funds', desc: 'Check if funds are available' },
];

// ============================================================================
// COMPONENT
// ============================================================================

export const OpenBankingSetupModal: React.FC<OpenBankingSetupProps> = ({
  isOpen,
  onClose,
  connectorCode,
  connectorName,
  onInitiateAuth,
  onFetchAspsps,
}) => {
  const [step, setStep] = useState(1);
  const [selectedCountry, setSelectedCountry] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [aspsps, setAspsps] = useState<Aspsp[]>([]);
  const [selectedAspsp, setSelectedAspsp] = useState<Aspsp | null>(null);
  const [selectedPermissions, setSelectedPermissions] = useState<string[]>(['AIS']);
  const [loading, setLoading] = useState(false);
  const [authorizing, setAuthorizing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch ASPSPs when country changes
  useEffect(() => {
    if (selectedCountry) {
      setLoading(true);
      setError(null);
      onFetchAspsps(selectedCountry, searchTerm)
        .then(data => {
          setAspsps(data);
          setLoading(false);
        })
        .catch(err => {
          setError('Failed to load banks');
          setLoading(false);
        });
    }
  }, [selectedCountry, onFetchAspsps]);

  // Filter ASPSPs by search
  const filteredAspsps = aspsps.filter(a =>
    a.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (a.bic && a.bic.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleInitiateAuth = async () => {
    if (!selectedAspsp) return;

    setAuthorizing(true);
    setError(null);

    try {
      const response = await onInitiateAuth(selectedAspsp.aspspId, selectedPermissions);
      // Redirect to bank authorization URL
      window.location.href = response.authorizationUrl;
    } catch (err) {
      setError('Failed to initiate authorization');
      setAuthorizing(false);
    }
  };

  const togglePermission = (permId: string) => {
    if (permId === 'AIS') return; // AIS is always required
    setSelectedPermissions(prev =>
      prev.includes(permId)
        ? prev.filter(p => p !== permId)
        : [...prev, permId]
    );
  };

  const resetAndClose = () => {
    setStep(1);
    setSelectedCountry('');
    setSearchTerm('');
    setAspsps([]);
    setSelectedAspsp(null);
    setSelectedPermissions(['AIS']);
    setError(null);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={resetAndClose} title="" size="lg">
      <div className="min-h-[500px] flex flex-col">
        {/* Header */}
        <div className="pb-6 border-b border-neutral-200 mb-6 dark:border-primary-800">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-neutral-900 flex items-center justify-center">
              <Globe className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-lg font-medium text-neutral-900 dark:text-neutral-50">Connect via {connectorName}</h2>
              <p className="text-sm text-neutral-500 dark:text-neutral-400">Securely link your bank account</p>
            </div>
          </div>
        </div>

        {/* Step Indicator */}
        <div className="flex items-center gap-1 mb-8">
          {['Select Country', 'Choose Bank', 'Permissions', 'Authorize'].map((label, idx) => (
            <React.Fragment key={idx}>
              <div className={cn(
                "flex items-center gap-2 px-3 py-1.5 text-xs font-medium transition-colors",
                step === idx + 1 && "bg-neutral-900 text-white",
                step > idx + 1 && "bg-neutral-100 text-neutral-900 dark:bg-primary-800 dark:text-neutral-50",
                step < idx + 1 && "text-neutral-400"
              )}>
                {step > idx + 1 ? <Check className="w-3 h-3" /> : <span>{idx + 1}</span>}
                <span className="hidden sm:inline">{label}</span>
              </div>
              {idx < 3 && <div className={cn("flex-1 h-px", step > idx + 1 ? "bg-neutral-900" : "bg-neutral-200")} />}
            </React.Fragment>
          ))}
        </div>

        {/* Error Display */}
        {error && (
          <div className="mb-4 p-3 bg-error-50 border border-error-200 flex items-center gap-2 dark:bg-error-500/10 dark:border-error-500/30">
            <AlertCircle className="w-4 h-4 text-error-600 dark:text-error-300" />
            <span className="text-sm text-error-700 dark:text-error-300">{error}</span>
          </div>
        )}

        {/* Step Content */}
        <div className="flex-1">
          {/* Step 1: Country Selection */}
          {step === 1 && (
            <div className="space-y-4">
              <p className="text-sm text-neutral-600 dark:text-neutral-300">Select the country where your bank is located:</p>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                {countries.map(country => (
                  <button
                    key={country.code}
                    onClick={() => {
                      setSelectedCountry(country.code);
                      setStep(2);
                    }}
                    className={cn(
                      "p-3 border text-left transition-all hover:border-neutral-400",
                      selectedCountry === country.code
                        ? "border-neutral-900 bg-neutral-900 text-white"
                        : "border-neutral-200 dark:border-primary-800"
                    )}
                  >
                    <span className="text-lg">{country.flag}</span>
                    <p className="text-xs mt-1 font-medium">{country.name}</p>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Step 2: Bank Selection */}
          {step === 2 && (
            <div className="space-y-4">
              <div className="relative">
                <Search className="w-4 h-4 text-neutral-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  placeholder="Search for your bank..."
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2.5 border border-neutral-300 text-sm focus:border-neutral-900 focus:outline-none dark:border-primary-700"
                />
              </div>

              {loading ? (
                <div className="py-12 text-center">
                  <Loader2 className="w-6 h-6 text-neutral-400 animate-spin mx-auto mb-2" />
                  <p className="text-sm text-neutral-500 dark:text-neutral-400">Loading banks...</p>
                </div>
              ) : (
                <div className="max-h-64 overflow-y-auto border border-neutral-200 dark:border-primary-800">
                  {filteredAspsps.length === 0 ? (
                    <div className="p-6 text-center text-sm text-neutral-500 dark:text-neutral-400">
                      No banks found
                    </div>
                  ) : (
                    filteredAspsps.map(aspsp => (
                      <button
                        key={aspsp.aspspId}
                        onClick={() => {
                          setSelectedAspsp(aspsp);
                          setStep(3);
                        }}
                        className={cn(
                          "w-full p-4 flex items-center justify-between border-b border-neutral-100 last:border-0 hover:bg-neutral-50 transition-colors dark:border-primary-800/60",
                          selectedAspsp?.aspspId === aspsp.aspspId && "bg-neutral-50 dark:bg-primary-950"
                        )}
                      >
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-neutral-100 flex items-center justify-center dark:bg-primary-800">
                            {aspsp.logoUrl ? (
                              <img src={aspsp.logoUrl} alt={aspsp.name} className="w-6 h-6 object-contain" />
                            ) : (
                              <Building2 className="w-5 h-5 text-neutral-500 dark:text-neutral-400" />
                            )}
                          </div>
                          <div className="text-left">
                            <p className="text-sm font-medium text-neutral-900 dark:text-neutral-50">{aspsp.name}</p>
                            {aspsp.bic && <p className="text-xs text-neutral-500 dark:text-neutral-400">{aspsp.bic}</p>}
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {aspsp.supportsAis && <span className="px-1.5 py-0.5 text-xs bg-neutral-100 text-neutral-600 dark:bg-primary-800 dark:text-neutral-300">AIS</span>}
                          {aspsp.supportsPis && <span className="px-1.5 py-0.5 text-xs bg-neutral-100 text-neutral-600 dark:bg-primary-800 dark:text-neutral-300">PIS</span>}
                          <ChevronRight className="w-4 h-4 text-neutral-400" />
                        </div>
                      </button>
                    ))
                  )}
                </div>
              )}
            </div>
          )}

          {/* Step 3: Permissions */}
          {step === 3 && selectedAspsp && (
            <div className="space-y-6">
              <div className="p-4 bg-neutral-50 border border-neutral-200 dark:bg-primary-950 dark:border-primary-800">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white border border-neutral-200 flex items-center justify-center dark:bg-primary-900 dark:border-primary-800">
                    <Building2 className="w-5 h-5 text-neutral-600 dark:text-neutral-300" />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-neutral-900 dark:text-neutral-50">{selectedAspsp.name}</p>
                    <p className="text-xs text-neutral-500 dark:text-neutral-400">{selectedAspsp.bic || selectedAspsp.country}</p>
                  </div>
                </div>
              </div>

              <div>
                <p className="text-xs font-medium text-neutral-600 uppercase tracking-wide mb-3 dark:text-neutral-300">Select Permissions</p>
                <div className="space-y-2">
                  {permissionOptions.map(perm => {
                    const isSupported = 
                      (perm.id === 'AIS' && selectedAspsp.supportsAis) ||
                      (perm.id === 'PIS' && selectedAspsp.supportsPis) ||
                      (perm.id === 'COF' && selectedAspsp.supportsCof);
                    const isSelected = selectedPermissions.includes(perm.id);
                    const isRequired = perm.id === 'AIS';

                    return (
                      <button
                        key={perm.id}
                        onClick={() => isSupported && togglePermission(perm.id)}
                        disabled={!isSupported || isRequired}
                        className={cn(
                          "w-full p-4 border text-left transition-all flex items-center justify-between",
                          isSelected && isSupported && "border-neutral-900 bg-neutral-900 text-white",
                          !isSelected && isSupported && "border-neutral-200 hover:border-neutral-400 dark:border-primary-800",
                          !isSupported && "border-neutral-100 bg-neutral-50 opacity-50 cursor-not-allowed dark:border-primary-800/60 dark:bg-primary-950"
                        )}
                      >
                        <div>
                          <p className={cn("text-sm font-medium", isSelected && isSupported ? "text-white" : "text-neutral-900 dark:text-neutral-50")}>
                            {perm.label}
                            {isRequired && <span className="ml-1 text-xs opacity-60">(Required)</span>}
                          </p>
                          <p className={cn("text-xs mt-0.5", isSelected && isSupported ? "text-neutral-300" : "text-neutral-500 dark:text-neutral-400")}>
                            {perm.desc}
                          </p>
                        </div>
                        {isSelected && isSupported && <Check className="w-5 h-5" />}
                        {!isSupported && <span className="text-xs text-neutral-400">Not supported</span>}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className="p-4 bg-info-50 border border-info-200 dark:bg-info-500/10 dark:border-info-500/30">
                <div className="flex items-start gap-2">
                  <Shield className="w-4 h-4 text-info-600 mt-0.5 dark:text-info-300" />
                  <div>
                    <p className="text-xs font-medium text-info-800 dark:text-info-300">Secure Authorization</p>
                    <p className="text-xs text-info-700 mt-0.5 dark:text-info-300">
                      You will be redirected to {selectedAspsp.name} to securely authorize access. 
                      We never see your login credentials.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Step 4: Authorization */}
          {step === 4 && selectedAspsp && (
            <div className="text-center py-8">
              {authorizing ? (
                <div>
                  <Loader2 className="w-12 h-12 text-neutral-400 animate-spin mx-auto mb-4" />
                  <p className="text-sm font-medium text-neutral-900 dark:text-neutral-50">Preparing Authorization</p>
                  <p className="text-xs text-neutral-500 mt-1 dark:text-neutral-400">Redirecting to {selectedAspsp.name}...</p>
                </div>
              ) : (
                <div>
                  <div className="w-16 h-16 bg-neutral-100 flex items-center justify-center mx-auto mb-4 dark:bg-primary-800">
                    <Shield className="w-8 h-8 text-neutral-600 dark:text-neutral-300" />
                  </div>
                  <p className="text-sm font-medium text-neutral-900 dark:text-neutral-50">Ready to Authorize</p>
                  <p className="text-xs text-neutral-500 mt-1 max-w-sm mx-auto dark:text-neutral-400">
                    Click below to connect to {selectedAspsp.name}. You'll be redirected to your bank to complete authorization.
                  </p>
                  <div className="mt-6 p-4 bg-neutral-50 border border-neutral-200 text-left max-w-sm mx-auto dark:bg-primary-950 dark:border-primary-800">
                    <p className="text-xs text-neutral-500 mb-2 dark:text-neutral-400">Selected Permissions</p>
                    <div className="flex flex-wrap gap-1">
                      {selectedPermissions.map(p => (
                        <span key={p} className="px-2 py-0.5 text-xs bg-neutral-900 text-white">{p}</span>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-between pt-6 mt-6 border-t border-neutral-200 dark:border-primary-800">
          <button
            onClick={step === 1 ? resetAndClose : () => setStep(step - 1)}
            className="px-4 py-2 text-sm text-neutral-600 hover:text-neutral-900 transition-colors dark:text-neutral-300"
            disabled={authorizing}
          >
            {step === 1 ? 'Cancel' : 'Back'}
          </button>
          {step === 3 && (
            <button
              onClick={() => setStep(4)}
              className="px-6 py-2 bg-neutral-900 text-white text-sm font-medium hover:bg-neutral-800 transition-colors"
            >
              Continue
            </button>
          )}
          {step === 4 && (
            <button
              onClick={handleInitiateAuth}
              disabled={authorizing}
              className="px-6 py-2 bg-neutral-900 text-white text-sm font-medium hover:bg-neutral-800 transition-colors disabled:opacity-50"
            >
              {authorizing ? 'Redirecting...' : 'Authorize with Bank'}
            </button>
          )}
        </div>
      </div>
    </Modal>
  );
};

export default OpenBankingSetupModal;

/**
 * Template Selector Modal Component
 * 
 * A modal dialog for selecting and previewing hierarchy templates
 * during program initialization.
 * 
 * Usage:
 *   import TemplateSelectorModal from './TemplateSelectorModal';
 *   
 *   <TemplateSelectorModal
 *     isOpen={showModal}
 *     program={selectedProgram}
 *     onClose={() => setShowModal(false)}
 *     onSelect={(templateId) => handleInitialize(templateId)}
 *     loading={initLoading}
 *   />
 */

import React, { useState, useEffect } from 'react';
import {
  Play,
  Info,
  FolderTree,
  ChevronRight,
} from 'lucide-react';
import { Modal } from '../components/ui/enhanced';
import { Button, Badge } from '../components/ui';
import { cn } from '../utils';
import {
  HIERARCHY_TEMPLATES,
  TemplateConfig,
  getRecommendedTemplate,
  getTemplatesForProgramType,
} from '../config/templateHierarchy';

// ============================================================================
// TYPES
// ============================================================================

interface Program {
  id: string;
  programCode: string;
  programName: string;
  programType: string;
  currencyCode: string;
  status: string;
}

interface TemplateSelectorModalProps {
  /** Whether the modal is open */
  isOpen: boolean;
  /** The program to initialize hierarchy for */
  program: Program | null;
  /** Called when modal is closed */
  onClose: () => void;
  /** Called when a template is selected and confirmed */
  onSelect: (templateId: string) => void;
  /** Whether initialization is in progress */
  loading?: boolean;
}

// ============================================================================
// COMPONENT
// ============================================================================

const TemplateSelectorModal: React.FC<TemplateSelectorModalProps> = ({
  isOpen,
  program,
  onClose,
  onSelect,
  loading = false,
}) => {
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [previewTemplate, setPreviewTemplate] = useState<TemplateConfig | null>(null);

  // Auto-select recommended template when program changes
  useEffect(() => {
    if (program) {
      const recommended = getRecommendedTemplate(program.programType);
      if (recommended) {
        setSelectedTemplate(recommended.id);
        setPreviewTemplate(recommended);
      } else {
        // Fall back to first available template
        const templates = getTemplatesForProgramType(program.programType);
        if (templates.length > 0) {
          setSelectedTemplate(templates[0].id);
          setPreviewTemplate(templates[0]);
        }
      }
    }
  }, [program]);

  // Reset state when modal closes
  useEffect(() => {
    if (!isOpen) {
      setSelectedTemplate(null);
      setPreviewTemplate(null);
    }
  }, [isOpen]);

  if (!program) return null;

  // Categorize templates
  const relevantTemplates = HIERARCHY_TEMPLATES.filter((t) =>
    t.forProgramTypes.includes(program.programType)
  );
  const otherTemplates = HIERARCHY_TEMPLATES.filter(
    (t) => !t.forProgramTypes.includes(program.programType)
  );

  const handleTemplateClick = (template: TemplateConfig) => {
    setSelectedTemplate(template.id);
    setPreviewTemplate(template);
  };

  const handleConfirm = () => {
    if (selectedTemplate) {
      onSelect(selectedTemplate);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      size="xl"
      title="Initialize Program Hierarchy"
    >
      <div className="flex gap-6 min-h-[500px] max-h-[70vh]">
        {/* ─────────────────────────────────────────────────────────────────── */}
        {/* LEFT PANEL: Template List */}
        {/* ─────────────────────────────────────────────────────────────────── */}
        <div className="w-1/2 overflow-y-auto pr-4 border-r border-neutral-200 dark:border-primary-800">
          <p className="text-sm text-neutral-600 mb-4 dark:text-neutral-300">
            Select a hierarchy template for{' '}
            <strong>{program.programName}</strong> ({program.programType})
          </p>

          {/* Recommended Templates */}
          {relevantTemplates.length > 0 && (
            <>
              <h3 className="text-xs font-semibold text-neutral-500 uppercase tracking-wider mb-2 dark:text-neutral-400">
                Recommended for {program.programType}
              </h3>
              <div className="space-y-2 mb-6">
                {relevantTemplates.map((template) => {
                  const Icon = template.icon;
                  const isSelected = selectedTemplate === template.id;

                  return (
                    <div
                      key={template.id}
                      onClick={() => handleTemplateClick(template)}
                      className={cn(
                        'p-4 border rounded-lg cursor-pointer transition-all',
                        isSelected
                          ? 'border-primary-500 bg-primary-50 ring-2 ring-primary-500 dark:bg-primary-800/40'
                          : 'border-neutral-200 hover:border-neutral-300 hover:bg-neutral-50 dark:border-primary-800'
                      )}
                    >
                      <div className="flex items-start gap-3">
                        <div
                          className={cn(
                            'w-10 h-10 rounded-lg flex items-center justify-center shrink-0',
                            template.bgColor
                          )}
                        >
                          <Icon className={cn('w-5 h-5', template.color)} />
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="font-medium text-primary-900 dark:text-neutral-50">
                              {template.name}
                            </span>
                            {template.recommended && (
                              <Badge variant="success" size="sm">
                                Recommended
                              </Badge>
                            )}
                          </div>
                          <p className="text-xs text-neutral-500 mt-1 dark:text-neutral-400">
                            {template.description}
                          </p>
                          <p className="text-xs text-neutral-400 mt-1">
                            {template.levels.length} hierarchy levels
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}

          {/* Other Templates */}
          {otherTemplates.length > 0 && (
            <>
              <h3 className="text-xs font-semibold text-neutral-500 uppercase tracking-wider mb-2 dark:text-neutral-400">
                Other Templates
              </h3>
              <div className="space-y-2">
                {otherTemplates.map((template) => {
                  const Icon = template.icon;
                  const isSelected = selectedTemplate === template.id;

                  return (
                    <div
                      key={template.id}
                      onClick={() => handleTemplateClick(template)}
                      className={cn(
                        'p-3 border rounded-lg cursor-pointer transition-all',
                        isSelected
                          ? 'border-primary-500 bg-primary-50 ring-2 ring-primary-500 opacity-100 dark:bg-primary-800/40'
                          : 'border-neutral-200 hover:border-neutral-300 opacity-60 hover:opacity-100 dark:border-primary-800'
                      )}
                    >
                      <div className="flex items-center gap-3">
                        <div
                          className={cn(
                            'w-8 h-8 rounded-lg flex items-center justify-center shrink-0',
                            template.bgColor
                          )}
                        >
                          <Icon className={cn('w-4 h-4', template.color)} />
                        </div>
                        <div className="flex-1 min-w-0">
                          <span className="text-sm font-medium text-primary-900 dark:text-neutral-50">
                            {template.name}
                          </span>
                          <p className="text-xs text-neutral-500 dark:text-neutral-400">
                            {template.levels.length} levels •{' '}
                            {template.forProgramTypes.join(', ')}
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>

        {/* ─────────────────────────────────────────────────────────────────── */}
        {/* RIGHT PANEL: Template Preview */}
        {/* ─────────────────────────────────────────────────────────────────── */}
        <div className="w-1/2 overflow-y-auto">
          {previewTemplate ? (
            <div>
              {/* Template Header */}
              <div className="flex items-center gap-3 mb-4">
                <div
                  className={cn(
                    'w-12 h-12 rounded-xl flex items-center justify-center shrink-0',
                    previewTemplate.bgColor
                  )}
                >
                  <previewTemplate.icon
                    className={cn('w-6 h-6', previewTemplate.color)}
                  />
                </div>
                <div>
                  <h3 className="font-semibold text-primary-900 dark:text-neutral-50">
                    {previewTemplate.name}
                  </h3>
                  <p className="text-sm text-neutral-500 dark:text-neutral-400">
                    {previewTemplate.levels.length} hierarchy levels
                  </p>
                </div>
              </div>

              {/* Hierarchy Structure */}
              <div className="bg-neutral-50 rounded-lg p-4 mb-4 dark:bg-primary-950">
                <h4 className="text-sm font-medium text-primary-900 mb-3 dark:text-neutral-50">
                  Hierarchy Structure
                </h4>
                <div className="space-y-1">
                  {previewTemplate.levels.map((level, index) => (
                    <div key={level.levelNumber} className="flex items-start gap-3">
                      {/* Level Number Indicator */}
                      <div className="flex flex-col items-center">
                        <div
                          className={cn(
                            'w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium shrink-0',
                            index === 0
                              ? 'bg-primary-600 text-white'
                              : index === previewTemplate.levels.length - 1
                              ? 'bg-success-600 text-white'
                              : 'bg-neutral-200 text-neutral-700 dark:text-neutral-200'
                          )}
                        >
                          {level.levelNumber}
                        </div>
                        {index < previewTemplate.levels.length - 1 && (
                          <div className="w-0.5 h-6 bg-neutral-300" />
                        )}
                      </div>

                      {/* Level Details */}
                      <div className="flex-1 pb-2 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-medium text-primary-900 dark:text-neutral-50">
                            {level.levelName}
                          </span>
                          <Badge variant="default" size="sm">
                            {level.dimensionType}
                          </Badge>
                          {level.isRequired && (
                            <Badge variant="warning" size="sm">
                              Required
                            </Badge>
                          )}
                        </div>
                        {level.description && (
                          <p className="text-xs text-neutral-500 mt-0.5 dark:text-neutral-400">
                            {level.description}
                          </p>
                        )}
                        {level.allowedValues && level.allowedValues.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-1">
                            {level.allowedValues.slice(0, 4).map((v) => (
                              <span
                                key={v}
                                className="text-xs px-1.5 py-0.5 bg-neutral-200 rounded"
                              >
                                {v}
                              </span>
                            ))}
                            {level.allowedValues.length > 4 && (
                              <span className="text-xs text-neutral-500 dark:text-neutral-400">
                                +{level.allowedValues.length - 4} more
                              </span>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* What Will Be Created */}
              <div className="bg-info-50 border border-info-200 rounded-lg p-3 dark:bg-info-500/10 dark:border-info-500/30">
                <div className="flex items-start gap-2">
                  <Info className="w-4 h-4 text-info-600 mt-0.5 shrink-0 dark:text-info-300" />
                  <div className="text-sm text-info-800 dark:text-info-300">
                    <p className="font-medium">What will be created:</p>
                    <ul className="mt-1 space-y-1 text-info-700 dark:text-info-300">
                      <li>• Root hierarchy node for the program</li>
                      <li>
                        • <strong>Exception VA</strong> ({program.currencyCode}) -
                        catches unmatched transactions
                      </li>
                      <li>
                        • Level configuration with {previewTemplate.levels.length}{' '}
                        tiers
                      </li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            /* Empty State */
            <div className="flex items-center justify-center h-full text-neutral-400">
              <div className="text-center">
                <FolderTree className="w-12 h-12 mx-auto mb-3" />
                <p>Select a template to preview</p>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ─────────────────────────────────────────────────────────────────── */}
      {/* FOOTER */}
      {/* ─────────────────────────────────────────────────────────────────── */}
      <div className="flex justify-between items-center pt-4 border-t mt-4">
        <p className="text-xs text-neutral-500 dark:text-neutral-400">
          You can add Settlement VAs at any level after initialization
        </p>
        <div className="flex gap-2">
          <Button variant="ghost" onClick={onClose} disabled={loading}>
            Cancel
          </Button>
          <Button
            onClick={handleConfirm}
            disabled={!selectedTemplate || loading}
            loading={loading}
            leftIcon={<Play className="w-4 h-4" />}
          >
            Initialize Hierarchy
          </Button>
        </div>
      </div>
    </Modal>
  );
};

