import React, { useState, useEffect } from 'react';
import {
  Building2, Crown, Landmark, Users, Briefcase, ArrowLeftRight,
  FlaskConical, Building, AlertTriangle, Lock, CheckCircle,
  ChevronDown, ChevronUp, Loader2, Wallet,
