// ============================================================================
// EXTENDED TYPES FOR ISO20022 FIELDS
// ============================================================================

// Extended Entry Details for camt.053/054
interface ISO20022EntryDetails {
  // Transaction References
  messageId?: string;
  endToEndId?: string;
  transactionId?: string;
  instructionId?: string;
  accountServicerRef?: string;
  paymentInfoId?: string;
  mandateId?: string;
  chequeNumber?: string;
  clearingSystemRef?: string;

  // Bank Transaction Code (Domain/Family/SubFamily)
  bankTransactionCode?: {
    domain?: string;
    family?: string;
    subFamily?: string;
    proprietaryCode?: string;
    proprietaryIssuer?: string;
  };

  // Related Parties
  debtor?: {
    name?: string;
    postalAddress?: string;
    accountIban?: string;
    accountOther?: string;
    agentBic?: string;
    agentName?: string;
  };
  creditor?: {
    name?: string;
    postalAddress?: string;
    accountIban?: string;
    accountOther?: string;
    agentBic?: string;
    agentName?: string;
  };
  ultimateDebtor?: {
    name?: string;
    identification?: string;
  };
  ultimateCreditor?: {
    name?: string;
    identification?: string;
  };

  // Remittance Information
  remittanceInfo?: {
    unstructured?: string[];
    structured?: {
      referredDocuments?: Array<{
        type?: string;
        number?: string;
        relatedDate?: string;
      }>;
      creditorReference?: string;
      invoiceNumber?: string;
      invoiceDate?: string;
      invoiceAmount?: number;
    };
  };

  // Additional Entry Info
  additionalInfo?: string;
  returnInfo?: {
    originalReference?: string;
    reason?: string;
    additionalInfo?: string;
  };

  // Charges
  charges?: Array<{
    amount: number;
    currency: string;
    bearer?: string;
    agent?: string;
  }>;

  // Exchange Rate Info
  exchangeRate?: {
    originalAmount?: number;
    originalCurrency?: string;
    rate?: number;
    contractId?: string;
  };
}

// Extended Statement Entry with full details
interface ExtendedStatementEntry extends StatementEntry {
  // Entry Reference (NtryRef)
  entryReference?: string;
  // Account Servicer Reference
  accountServicerRef?: string;
  // Reversal Indicator
  reversalIndicator?: boolean;
  // Bank Transaction Code
  bankTransactionCode?: string;
  // Additional Entry Info
  additionalEntryInfo?: string;
  // Entry Details (expandable)
  entryDetails?: ISO20022EntryDetails;
  // Batch information (for batch entries)
  batchInfo?: {
    numberOfTransactions?: number;
    totalAmount?: number;
  };
}

// Extended Statement with full ISO20022 fields
interface ExtendedISO20022Statement extends ISO20022Statement {
  // Group Header (GrpHdr)
  groupHeader?: {
    messageId: string;
    creationDateTime: string;
    messagePagination?: {
      pageNumber: number;
      lastPageIndicator: boolean;
    };
    additionalInfo?: string;
  };

  // Notification specific (camt.054)
  notificationInfo?: {
    notificationId?: string;
    notificationType?: 'CREDIT' | 'DEBIT';
    priority?: 'HIGH' | 'NORMAL' | 'LOW';
    realTimeTimestamp?: string;
  };

  // Extended entries
  entries: ExtendedStatementEntry[];
}

