  { id: 'ag5', agentCode: 'AGT-005', agentName: 'Sharjah City Center', agentType: 'RETAIL', location: 'Sharjah', status: 'SUSPENDED', floatBalance: 25000, dailyLimit: 75000, dailyUsed: 0, transactionCount: 0 },
];

