  childCount: number;
  children?: HierarchyBalance[];
  fxRate?: number;
  lastUpdated?: string;
  status?: string;
}

interface AggregationSummary {
  corporateId: string;
  baseCurrency: string;
  totalBalanceBase: number;
  totalAccounts: number;
  currencyCount: number;
  lastAggregatedAt: string;
}

interface Corporate {
  id: string;
  corporateId: string;
  legalName: string;
  tradeName?: string;
  shortName?: string;
  status: string;
}

interface ProgramOption {
  id: string;
  programName: string;
  programCode: string;
  currencyCode: string;
  programType: string;
  status: string;
  corporateId?: string;
}

// Helper
const extractData = <T,>(response: ApiResponse<T>): T => {
  if (response && response.data !== undefined) return response.data;
  return response as unknown as T;
};

