const EnhancedPayablesPage: React.FC = () => {
  const { navigate } = useNavigation();

  // Selection state
  const [corporates, setCorporates] = useState<Corporate[]>([]);
  const [programs, setPrograms] = useState<Program[]>([]);
  const [entities, setEntities] = useState<LegalEntity[]>([]);
  const [selectedCorporateId, setSelectedCorporateId] = useState('');
  const [selectedProgramId, setSelectedProgramId] = useState('');
  const [selectedEntityId, setSelectedEntityId] = useState('');

  // Data state
  const [payables, setPayables] = useState<PayablePhase2[]>([]);
  const [stats, setStats] = useState<PayableStatsPhase2 | null>(null);
  const [loading, setLoading] = useState(false);
  const [statsLoading, setStatsLoading] = useState(false);
  const [corporatesLoading, setCorporatesLoading] = useState(true);

  // UI state
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState('all');
  const [currentPage, setCurrentPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [showPoboModal, setShowPoboModal] = useState(false);
  const [poboPayables, setPoboPayables] = useState<PayablePhase2[]>([]);
  const [submitting, setSubmitting] = useState(false);

  // Approval modal state
  const [showApprovalModal, setShowApprovalModal] = useState(false);
  const [approvalPayable, setApprovalPayable] = useState<PayablePhase2 | null>(null);
  const [approvalAction, setApprovalAction] = useState<'approve' | 'reject' | 'submit'>('approve');
  const [approvalLoading, setApprovalLoading] = useState(false);

  // Load corporates on mount
  useEffect(() => {
    const loadCorporates = async () => {
      setCorporatesLoading(true);
      try {
        const result = await corporatesApi.getAll();
        const corpList = Array.isArray(result) ? result : (result as any)?.data || [];
        setCorporates(corpList);
        // Auto-select first corporate
        if (corpList.length > 0) {
          setSelectedCorporateId(corpList[0].id);
        }
      } catch (error) {
        console.error('Failed to load corporates:', error);
        setCorporates([]);
      } finally {
        setCorporatesLoading(false);
      }
    };
    loadCorporates();
  }, []);

  // Load programs when corporate changes
  useEffect(() => {
    if (!selectedCorporateId) {
      setPrograms([]);
      return;
    }

    const loadPrograms = async () => {
      try {
        const result = await programsApi.getAll({ corporateId: selectedCorporateId });
        const progList = Array.isArray(result) ? result : (result as any)?.content || (result as any)?.data || [];
        setPrograms(progList);
      } catch (error) {
        console.error('Failed to load programs:', error);
        setPrograms([]);
      }
    };
    loadPrograms();
  }, [selectedCorporateId]);

  // Load legal entities when corporate changes
  useEffect(() => {
    if (!selectedCorporateId) {
      setEntities([]);
      return;
    }

    const loadEntities = async () => {
      try {
        const result = await legalEntityApi.getByCorporate(selectedCorporateId);
        const entList = Array.isArray(result) ? result : (result as any)?.data || [];
        setEntities(entList);
      } catch (error) {
        console.error('Failed to load entities:', error);
        setEntities([]);
      }
    };
    loadEntities();
  }, [selectedCorporateId]);

  // Load payables
  const loadPayables = useCallback(async () => {
    // Corporates load asynchronously on mount (see loadCorporates above), so
    // selectedCorporateId is '' for the first render or two. Searching with
    // no corporate scope fires an unscoped "all payables" query that briefly
    // flashes the wrong data before the real corporate resolves and the
    // effect re-fires (see loadStats below for the worse version of this
    // race, where it used to shadow-swap the corporate entirely).
    if (!selectedCorporateId) {
      setPayables([]);
      setTotalPages(0);
      return;
    }
    setLoading(true);
    try {
      // The Pending/Intercompany/POBO/Netting tabs filter client-side (see
      // filteredPayables below) on fields the search endpoint can't express
      // as a single-value query param (e.g. "pending" is status IN
      // (PENDING_APPROVAL, PENDING_POBO), and the backend only supports
      // exact-match equality, no IN/OR - see PayableRepository.searchPayables).
      // Paginating server-side at 20/page while filtering client-side meant
      // a tab could show "No payables found" whenever none of its matches
      // happened to land on the currently-loaded page, even though the tab's
      // own badge count (sourced from /payables/stats) said otherwise.
      // ponytail: fetch the whole corpus for a filtered tab instead of
      // teaching the backend query to do IN-clauses - correct at the demo's
      // realistic volumes (dozens, not thousands); revisit with real
      // server-side status-list filtering if a corporate's payables ever
      // outgrow one page.
      const isFilteredTab = activeTab !== 'all';
      const result = await payablesApiPhase2.search({
        corporateId: selectedCorporateId,
        programId: selectedProgramId || undefined,
        owningEntityId: selectedEntityId || undefined,
        searchTerm: searchTerm || undefined,
        page: isFilteredTab ? 0 : currentPage,
        size: isFilteredTab ? 1000 : 20,
        sortBy: 'createdAt',
        sortOrder: 'desc',
      });

      // Handle response - could be array or paginated response
      if (Array.isArray(result)) {
        setPayables(result);
        setTotalPages(1);
      } else if (result?.payables) {
        setPayables(result.payables);
        setTotalPages(isFilteredTab ? 1 : (result.totalPages || 1));
      } else if (result?.content) {
        setPayables(result.content);
        setTotalPages(isFilteredTab ? 1 : (result.totalPages || 1));
      } else {
        setPayables([]);
        setTotalPages(0);
      }
    } catch (error) {
      console.error('Failed to load payables:', error);
      setPayables([]);
    } finally {
      setLoading(false);
    }
  }, [selectedCorporateId, selectedProgramId, selectedEntityId, searchTerm, currentPage, activeTab]);

  // Load stats
  const loadStats = useCallback(async () => {
    // Don't fall back to a hardcoded demo corporate here: selectedCorporateId
    // is briefly '' while loadCorporates() (above) is still in flight on
    // mount, and querying stats for a different, hardcoded corporate in that
    // window used to race the real query below (whichever HTTP response
    // landed last won), showing e.g. "51 total payables" for a corporate
    // that was never the one selected while the table legitimately showed
    // zero rows for the real one. Just wait for the real corporate.
    if (!selectedCorporateId) {
      setStats(null);
      return;
    }
    setStatsLoading(true);
    try {
      const result = await payablesApiPhase2.getStats(
        selectedCorporateId,
        selectedProgramId || undefined,
        selectedEntityId || undefined
      );
      setStats(result);
    } catch (error) {
      console.error('Failed to load stats:', error);
      setStats(null);
    } finally {
      setStatsLoading(false);
    }
  }, [selectedCorporateId, selectedProgramId, selectedEntityId]);

  // Trigger data load when filters change
  useEffect(() => {
    loadPayables();
    loadStats();
  }, [loadPayables, loadStats]);

  // Filter payables based on active tab
  const filteredPayables = useMemo(() => {
    const payablesList = Array.isArray(payables) ? payables : [];
    switch (activeTab) {
      case 'pending':
        return payablesList.filter(p => p.status === 'PENDING_APPROVAL' || p.status === 'PENDING_POBO');
      case 'intercompany':
        return payablesList.filter(p => p.isIntercompany);
      case 'pobo':
        return payablesList.filter(p => p.paymentRoute === 'POBO' || p.poboRequestStatus === 'PENDING_TREASURY_APPROVAL');
      case 'netting':
        return payablesList.filter(p => p.nettingStatus === 'INCLUDED' || p.nettingEligible);
      default:
        return payablesList;
    }
  }, [payables, activeTab]);

  // Handlers
  const handleRequestPobo = (payable: PayablePhase2) => {
    setPoboPayables([payable]);
    setShowPoboModal(true);
  };

  const handleBulkPobo = () => {
    const selected = filteredPayables.filter(p => selectedIds.has(p.id) && p.canRequestPobo);
    if (selected.length > 0) {
      setPoboPayables(selected);
      setShowPoboModal(true);
    }
  };

  const handleSubmitPobo = async (payingEntityId: string, payableIds: string[]) => {
    setSubmitting(true);
    try {
      await payablesApiPhase2.requestPobo({
        payableIds,
        payingEntityId,
        requestedBy: 'current-user', // TODO: Get from auth
      });
      setShowPoboModal(false);
      setSelectedIds(new Set());
      loadPayables();
      loadStats();
    } catch (error) {
      console.error('Failed to submit POBO request:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleCorporateChange = (id: string) => {
    setSelectedCorporateId(id);
    setSelectedProgramId('');
    setSelectedEntityId('');
    setCurrentPage(0);
  };

  const handleProgramChange = (id: string) => {
    setSelectedProgramId(id);
    setCurrentPage(0);
  };

  const handleEntityChange = (id: string) => {
    setSelectedEntityId(id);
    setCurrentPage(0);
  };

  // Approval action handlers
  const handleApprove = (payable: PayablePhase2) => {
    setApprovalPayable(payable);
    setApprovalAction('approve');
    setShowApprovalModal(true);
  };

  const handleReject = (payable: PayablePhase2) => {
    setApprovalPayable(payable);
    setApprovalAction('reject');
    setShowApprovalModal(true);
  };

  const handleSubmitForApproval = (payable: PayablePhase2) => {
    setApprovalPayable(payable);
    setApprovalAction('submit');
    setShowApprovalModal(true);
  };

  const handleSchedule = (payable: PayablePhase2) => {
    // For now, just navigate to edit page with schedule mode
    // Could also implement a schedule modal later
    navigate('payables-edit', { id: payable.id, mode: 'schedule' });
  };

  const handleEdit = (payable: PayablePhase2) => {
    navigate('payables-edit', { id: payable.id });
  };

  const handlePayNow = async (payable: PayablePhase2) => {
    if (!confirm(`Execute payment of ${payable.netAmount} ${payable.currencyCode} to ${payable.vendorName}?`)) {
      return;
    }

    try {
      const currentUser = 'current-user'; // TODO: Get from auth context
      await payablesApiPhase2.executePayment(payable.id, currentUser);

      // Refresh data after payment
      await loadPayables();
      await loadStats();
      alert('Payment executed successfully!');
    } catch (error: any) {
      console.error('Failed to execute payment:', error);
      alert(`Failed to execute payment: ${error?.response?.data?.message || error?.message || 'Unknown error'}`);
    }
  };

  const handleApprovalAction = async (payableId: string, action: string, reason?: string) => {
    setApprovalLoading(true);
    try {
      const currentUser = 'current-user'; // TODO: Get from auth context

      if (action === 'approve') {
        await payablesApiPhase2.approve(payableId, currentUser, reason);
      } else if (action === 'reject') {
        await payablesApiPhase2.reject(payableId, currentUser, reason || 'Rejected by user');
      } else if (action === 'submit') {
        await payablesApiPhase2.submitForApproval(payableId, currentUser);
      }

      // Refresh data after action
      await loadPayables();
      await loadStats();
      setShowApprovalModal(false);
      setApprovalPayable(null);
    } catch (error: any) {
      console.error(`Failed to ${action} payable:`, error);
      alert(`Failed to ${action} payable: ${error?.response?.data?.message || error?.message || 'Unknown error'}`);
    } finally {
      setApprovalLoading(false);
    }
  };

  // Tab counts
  const tabCounts = useMemo(() => {
    const payablesList = Array.isArray(payables) ? payables : [];
    return {
      all: stats?.totalCount || payablesList.length,
      pending: stats?.pendingCount || payablesList.filter(p => p.status === 'PENDING_APPROVAL' || p.status === 'PENDING_POBO').length,
      intercompany: stats?.intercompanyCount || payablesList.filter(p => p.isIntercompany).length,
      pobo: stats?.poboRequestedCount || payablesList.filter(p => p.paymentRoute === 'POBO').length,
      netting: stats?.nettingIncludedCount || payablesList.filter(p => p.nettingStatus === 'INCLUDED').length,
    };
  }, [payables, stats]);

  const selectedPayables = filteredPayables.filter(p => selectedIds.has(p.id));

  return (
    <Page>
      {/* Quick Actions */}
      <div className="flex items-center justify-end gap-2 animate-fade-in" style={{ animationDelay: '0.05s' }}>
        <Button variant="outline" onClick={() => { loadPayables(); loadStats(); }} leftIcon={<RefreshCw className="w-4 h-4" />}>
          Refresh
        </Button>
        <Button variant="primary" leftIcon={<Plus className="w-4 h-4" />} onClick={() => {
          // Pass selected corporate and entity IDs to the create page
          const params: Record<string, string> = {};
          if (selectedCorporateId) {
            params.corporateId = selectedCorporateId;
          }
          if (selectedEntityId) {
            params.legalEntityId = selectedEntityId;
          }
          console.log('Navigate to payables-create with params:', params);
          navigate('payables-create', Object.keys(params).length > 0 ? params : undefined);
        }}>
          New Payable
        </Button>
      </div>

      {/* Filter Bar (matches TreasuryHierarchyPage) */}
      <PayablesFilterBar
        corporates={corporates}
        programs={programs}
        entities={entities}
        selectedCorporateId={selectedCorporateId}
        selectedProgramId={selectedProgramId}
        selectedEntityId={selectedEntityId}
        onCorporateChange={handleCorporateChange}
        onProgramChange={handleProgramChange}
        onEntityChange={handleEntityChange}
        loading={corporatesLoading}
      />

      {/* Stats */}
      <PayablesStatsSection stats={stats} loading={statsLoading} />

      {/* Main Content Card */}
      <Card className="animate-fade-in" style={{ animationDelay: '0.4s' }}>
        <div className="h-1 bg-gradient-to-r from-primary-50/50 via-white to-primary-50/50 rounded-t-xl dark:from-primary-900 dark:via-primary-900 dark:to-primary-900" />

        {/* Tabs & Search */}
        <div className="flex items-center justify-between gap-4 px-4 pt-4 pb-2 border-b border-neutral-200 dark:border-primary-800">
          <div className="flex gap-1">
            {[
              { key: 'all', label: 'All', count: tabCounts.all },
              { key: 'pending', label: 'Pending', count: tabCounts.pending },
              { key: 'intercompany', label: 'Intercompany', count: tabCounts.intercompany },
              { key: 'pobo', label: 'POBO', count: tabCounts.pobo },
              { key: 'netting', label: 'Netting', count: tabCounts.netting },
            ].map(tab => (
              <button
                key={tab.key}
                onClick={() => { setActiveTab(tab.key); setCurrentPage(0); }}
                className={cn(
                  "px-4 py-2 text-sm font-medium border-b-2 transition-all duration-200",
                  activeTab === tab.key
                    ? "border-primary-600 text-primary-600 dark:text-primary-200"
                    : "border-transparent text-neutral-500 hover:text-neutral-700 dark:text-neutral-200 hover:border-neutral-300 dark:hover:border-primary-700 dark:text-neutral-400 dark:hover:text-neutral-200"
                )}
              >
                {tab.label}
                <span className={cn(
                  "ml-2 px-2 py-0.5 text-xs rounded-full transition-colors",
                  activeTab === tab.key ? "bg-primary-100 dark:bg-primary-700 text-primary-700 dark:text-neutral-200" : "bg-neutral-100 dark:bg-primary-800 text-neutral-600 dark:text-neutral-300"
                )}>{tab.count}</span>
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-neutral-400 dark:text-neutral-500" />
              <input
                type="text"
                placeholder="Search invoices..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-4 py-2 border border-neutral-200 dark:border-primary-800 rounded-lg text-sm bg-white dark:bg-primary-900 focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all w-64"
              />
            </div>
            {selectedIds.size > 0 && (
              <Button variant="outline" size="sm" onClick={handleBulkPobo} leftIcon={<Landmark className="w-4 h-4" />}>
                Request POBO ({selectedIds.size})
              </Button>
            )}
          </div>
        </div>

        {/* Table */}
        <DataTable
          data={filteredPayables}
          keyExtractor={(payable) => payable.id}
          loading={loading}
          selectable
          selectedKeys={selectedIds}
          onSelectionChange={(keys) => setSelectedIds(keys as Set<string>)}
          onRowClick={(payable) => navigate(`/payables/${payable.id}`)}
          pagination={totalPages > 1}
          pageSize={20}
          currentPage={currentPage + 1}
          totalCount={totalPages * 20}
          onPageChange={(p) => setCurrentPage(p - 1)}
          emptyIcon={<FileText className="w-12 h-12 text-neutral-300 dark:text-neutral-600" />}
          emptyTitle="No payables found"
          emptyDescription={!selectedCorporateId ? 'Select a corporate to view payables' : 'Try adjusting your filters'}
          columns={[
            {
              key: 'invoiceNumber',
              header: 'Invoice',
              render: (_, payable) => (
                <div>
                  <p className="font-medium text-primary-900 dark:text-neutral-50">{payable.invoiceNumber || payable.payableNumber}</p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400">{payable.payableNumber}</p>
                </div>
              ),
            },
            {
              key: 'vendorName',
              header: 'Vendor / Entity',
              render: (_, payable) => (
                <div>
                  <p className="font-medium text-sm text-primary-900 dark:text-neutral-50">{payable.vendorName}</p>
                  {payable.owningEntityCode && <p className="text-xs text-neutral-500 dark:text-neutral-400">{payable.owningEntityCode}</p>}
                </div>
              ),
            },
            {
              key: 'netAmount',
              header: 'Amount',
              align: 'right',
              render: (_, payable) => (
                <>
                  <p className="font-semibold text-primary-900 dark:text-neutral-50">{formatCurrency(payable.netAmount, payable.currencyCode)}</p>
                  {payable.outstandingAmount !== payable.netAmount && (
                    <p className="text-xs text-neutral-500 dark:text-neutral-400">Due: {formatCurrency(payable.outstandingAmount, payable.currencyCode)}</p>
                  )}
                </>
              ),
            },
            {
              key: 'dueDate',
              header: 'Due Date',
              render: (_, payable) => (
                <div className="flex flex-col gap-1">
                  <span className={cn("text-sm", payable.isOverdue ? "text-error-600 dark:text-error-300 font-medium" : "text-neutral-600 dark:text-neutral-300")}>
                    {formatDate(payable.dueDate)}
                  </span>
                  {payable.isOverdue && <Badge variant="error" size="sm">Overdue</Badge>}
                </div>
              ),
            },
            {
              key: 'status',
              header: 'Status',
              render: (_, payable) => (
                <div className="flex flex-col gap-1">
                  {getStatusBadge(payable.status)}
                  {getPoboStatusBadge(payable.poboRequestStatus)}
                </div>
              ),
            },
            { key: 'paymentRoute', header: 'Route', render: (_, payable) => getPaymentRouteBadge(payable.paymentRoute, payable.isIntercompany, payable.nettingStatus) },
            {
              key: 'actions',
              header: 'Actions',
              render: (_, payable) => (
                <PayableActionsCell
                  payable={payable}
                  onViewDetails={(p) => navigate(`/payables/${p.id}`)}
                  onRequestPobo={handleRequestPobo}
                  onApprove={handleApprove}
                  onReject={handleReject}
                  onSubmit={handleSubmitForApproval}
                  onEdit={handleEdit}
                  onPayNow={handlePayNow}
                />
              ),
            },
          ]}
        />
      </Card>

      {/* POBO Modal */}
      <PoboRequestModal
        isOpen={showPoboModal}
        onClose={() => setShowPoboModal(false)}
        payables={poboPayables}
        entities={entities}
        onSubmit={handleSubmitPobo}
        loading={submitting}
      />

      {/* Approval Modal */}
      <ApprovalModal
        isOpen={showApprovalModal}
        onClose={() => {
          setShowApprovalModal(false);
          setApprovalPayable(null);
        }}
        payable={approvalPayable}
        action={approvalAction}
        onConfirm={handleApprovalAction}
        loading={approvalLoading}
      />
    </Page>
  );
};

export default EnhancedPayablesPage;

/**
 * Enhanced POBO (Pay On Behalf Of) Component
 * 
 * Integrates with:
 * - In-House Bank (IHB) for intercompany loans
 * - Hierarchy for entity selection
 * - Tax/Charges for fee calculation
 */

import React, { useState, useEffect, useCallback } from 'react';
import {
  ArrowLeftRight, Building2, Landmark, CheckCircle, AlertCircle, AlertTriangle,
  ChevronDown, DollarSign, Info, Loader2, TrendingUp, TrendingDown, Percent,
  RefreshCw, Eye, Clock, CreditCard, ArrowRight, Shield, Banknote, FileText,
} from 'lucide-react';
import { Card, CardHeader, Button, Badge, Input } from '../components/ui';
import { Modal, ProgressBar } from '../components/ui/enhanced';
import { formatCurrency, formatDate, cn } from '../utils';
import { intercompanyApi, ihbIntegrationApi, HierarchyEntity, PoboRequest, PoboResult } from '../services/api';

// ============================================================================
// TYPES
// ============================================================================

interface EntityWithPosition extends HierarchyEntity {
  netPosition?: number;
  creditAvailable?: number;
  pendingPobo?: number;
  interestRate?: number;
}

interface PoboPreview {
  baseAmount: number;
  charges: { code: string; name: string; amount: number; waived: boolean }[];
  totalCharges: number;
  ihbLoanAmount: number;
  ihbInterestRate: number;
  estimatedInterest: number;
  netPayment: number;
  warnings: string[];
}

interface PoboComponentProps {
  enabled: boolean;
  onToggle: (enabled: boolean) => void;
  payingEntityId: string | null;
  behalfEntityId: string | null;
  onSelectPayingEntity: (id: string, name: string, entity: EntityWithPosition) => void;
  onSelectBehalfEntity: (id: string, name: string, entity: EntityWithPosition) => void;
  amount: number;
  currencyCode: string;
  onPreviewUpdate?: (preview: PoboPreview | null) => void;
}

// ============================================================================
// ENTITY POSITION CARD
// ============================================================================

const EntityPositionCard: React.FC<{
  entity: EntityWithPosition;
  role: 'PAYER' | 'BENEFICIARY';
  amount?: number;
}> = ({ entity, role, amount }) => {
  const isPositive = (entity.netPosition || 0) >= 0;
  const hasCapacity = (entity.creditAvailable || 0) >= (amount || 0);

  return (
    <div className="bg-white dark:bg-primary-900 rounded-lg border border-neutral-200 dark:border-primary-800 p-3 space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          {role === 'PAYER' ? (
            <Landmark className="w-4 h-4 text-primary-600 dark:text-primary-200" />
          ) : (
            <Building2 className="w-4 h-4 text-accent-600 dark:text-accent-300" />
          )}
          <span className="text-sm font-medium text-primary-900 dark:text-neutral-50">{entity.entityName}</span>
        </div>
        <Badge variant={entity.status === 'ACTIVE' ? 'success' : 'neutral'} size="sm">
          {entity.status}
        </Badge>
      </div>

      <div className="grid grid-cols-3 gap-2 text-xs">
        <div>
          <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Balance</p>
          <p className={cn('font-medium', isPositive ? 'text-success-600 dark:text-success-300' : 'text-error-600 dark:text-error-300')}>
            {formatCurrency(entity.currentBalance || 0, entity.currencyCode)}
          </p>
        </div>
        <div>
          <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Net Position</p>
          <p className={cn('font-medium', isPositive ? 'text-success-600 dark:text-success-300' : 'text-error-600 dark:text-error-300')}>
            {formatCurrency(entity.netPosition || 0, entity.currencyCode)}
          </p>
        </div>
        <div>
          <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Credit Available</p>
          <p className={cn('font-medium', hasCapacity ? 'text-info-600 dark:text-info-300' : 'text-warning-600 dark:text-warning-300')}>
            {formatCurrency(entity.creditAvailable || entity.creditLimit || 0, entity.currencyCode)}
          </p>
        </div>
      </div>

      {role === 'PAYER' && amount && !hasCapacity && (
        <div className="flex items-center gap-1 text-xs text-warning-600 dark:text-warning-300 bg-warning-50 dark:bg-warning-500/10 rounded p-2">
          <AlertTriangle className="w-3 h-3" />
          <span>Insufficient credit limit for this transaction</span>
        </div>
      )}

      {entity.pendingPobo && entity.pendingPobo > 0 && (
        <div className="flex items-center gap-1 text-xs text-info-600 dark:text-info-300">
          <Clock className="w-3 h-3" />
          <span>Pending POBO: {formatCurrency(entity.pendingPobo, entity.currencyCode)}</span>
        </div>
      )}
    </div>
  );
};

// ============================================================================
// IHB LOAN PREVIEW
// ============================================================================

const IhbLoanPreview: React.FC<{
  payingEntity: EntityWithPosition | null;
  behalfEntity: EntityWithPosition | null;
  amount: number;
  currencyCode: string;
  interestRate: number;
}> = ({ payingEntity, behalfEntity, amount, currencyCode, interestRate }) => {
  if (!payingEntity || !behalfEntity) return null;

  const dailyInterest = (amount * interestRate) / 100 / 365;
  const monthlyInterest = dailyInterest * 30;

  return (
    <Card className="bg-primary-50 border-primary-200 dark:bg-primary-800/40 dark:border-primary-700">
      <div className="flex items-center gap-2 mb-3">
        <CreditCard className="w-5 h-5 text-primary-600 dark:text-primary-200" />
        <h4 className="text-sm font-semibold text-primary-900 dark:text-neutral-50">IHB Intercompany Loan</h4>
      </div>

      <div className="space-y-3">
        {/* Flow Diagram */}
        <div className="flex items-center justify-between bg-white dark:bg-primary-900 rounded-lg p-3">
          <div className="text-center">
            <Landmark className="w-6 h-6 text-primary-600 mx-auto mb-1 dark:text-primary-200" />
            <p className="text-xs font-medium text-primary-900 dark:text-neutral-50">{payingEntity.entityCode}</p>
            <p className="text-xs text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Lender</p>
          </div>
          <div className="flex-1 flex items-center justify-center">
            <div className="flex items-center gap-2">
              <div className="w-12 h-0.5 bg-primary-300" />
              <ArrowRight className="w-5 h-5 text-primary-500" />
              <div className="flex flex-col items-center">
                <p className="text-sm font-bold text-primary-900 dark:text-neutral-50">{formatCurrency(amount, currencyCode)}</p>
                <p className="text-xs text-primary-600 dark:text-primary-200">@ {interestRate}% p.a.</p>
              </div>
              <ArrowRight className="w-5 h-5 text-primary-500" />
              <div className="w-12 h-0.5 bg-primary-300" />
            </div>
          </div>
          <div className="text-center">
            <Building2 className="w-6 h-6 text-accent-600 dark:text-accent-300 mx-auto mb-1" />
            <p className="text-xs font-medium text-primary-900 dark:text-neutral-50">{behalfEntity.entityCode}</p>
            <p className="text-xs text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Borrower</p>
          </div>
        </div>

        {/* Interest Breakdown */}
        <div className="grid grid-cols-3 gap-2 text-xs">
          <div className="bg-white dark:bg-primary-900 rounded p-2">
            <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Principal</p>
            <p className="font-semibold text-primary-900 dark:text-neutral-50">{formatCurrency(amount, currencyCode)}</p>
          </div>
          <div className="bg-white dark:bg-primary-900 rounded p-2">
            <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Daily Interest</p>
            <p className="font-semibold text-info-600 dark:text-info-300">{formatCurrency(dailyInterest, currencyCode)}</p>
          </div>
          <div className="bg-white dark:bg-primary-900 rounded p-2">
            <p className="text-neutral-500 dark:text-neutral-400 dark:text-neutral-500">Est. Monthly</p>
            <p className="font-semibold text-info-600 dark:text-info-300">{formatCurrency(monthlyInterest, currencyCode)}</p>
          </div>
        </div>

        <div className="flex items-center gap-2 text-xs text-primary-700 bg-white dark:bg-primary-900 rounded p-2 dark:text-neutral-200">
          <Info className="w-4 h-4" />
          <span>Loan will be automatically settled during monthly intercompany netting</span>
        </div>
      </div>
    </Card>
  );
};

// ============================================================================
// MAIN POBO COMPONENT
// ============================================================================

export const EnhancedPoboPicker: React.FC<PoboComponentProps> = ({
  enabled,
  onToggle,
  payingEntityId,
  behalfEntityId,
  onSelectPayingEntity,
  onSelectBehalfEntity,
  amount,
  currencyCode,
  onPreviewUpdate,
}) => {
  const [entities, setEntities] = useState<EntityWithPosition[]>([]);
  const [loading, setLoading] = useState(false);
  const [showPayingPicker, setShowPayingPicker] = useState(false);
  const [showBehalfPicker, setShowBehalfPicker] = useState(false);
  const [preview, setPreview] = useState<PoboPreview | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [validationWarnings, setValidationWarnings] = useState<string[]>([]);

  const payingEntity = entities.find(e => e.id === payingEntityId);
  const behalfEntity = entities.find(e => e.id === behalfEntityId);

  // Load entities with IHB positions
  useEffect(() => {
    const loadEntities = async () => {
      setLoading(true);
      try {
        const [entitiesRes] = await Promise.all([
          intercompanyApi.getEntities({ status: 'ACTIVE' }),
        ]);

        if (entitiesRes.success) {
          // Enrich with IHB positions
          const enriched = await Promise.all(
            entitiesRes.data.map(async (entity) => {
              if (entity.ihbEntityId) {
                const positionRes = await ihbIntegrationApi.getEntityPosition(entity.ihbEntityId);
                if (positionRes.success) {
                  const pos = positionRes.data;
                  return {
                    ...entity,
                    netPosition: pos.loansAsLender.reduce((sum, l) => sum + l.amount, 0) -
                                 pos.loansAsBorrower.reduce((sum, l) => sum + l.amount, 0),
                    creditAvailable: (entity.creditLimit || 0) - (pos.loansAsBorrower.reduce((sum, l) => sum + l.amount, 0)),
                  };
                }
              }
              return entity;
            })
          );
          setEntities(enriched);
        }
      } catch (error) {
        console.error('Failed to load entities:', error);
      } finally {
        setLoading(false);
      }
    };

    if (enabled) {
      loadEntities();
    }
  }, [enabled]);

  // Generate preview when entities and amount change
  useEffect(() => {
    const generatePreview = async () => {
      if (!payingEntityId || !behalfEntityId || amount <= 0) {
        setPreview(null);
        onPreviewUpdate?.(null);
        return;
      }

      setPreviewLoading(true);
      try {
        const previewRes = await intercompanyApi.previewPobo({
          payableId: '',
          payableNumber: '',
          vendorId: '',
          vendorName: '',
          vendorBankAccountId: '',
          payingEntityId,
          behalfEntityId,
          amount,
          currencyCode,
          paymentMethod: 'BANK_TRANSFER',
          priority: 'NORMAL',
        });

        if (previewRes.success) {
          const previewData: PoboPreview = {
            baseAmount: amount,
            charges: previewRes.data.estimatedCharges,
            totalCharges: previewRes.data.estimatedCharges.reduce((sum, c) => sum + (c.waived ? 0 : c.amount), 0),
            ihbLoanAmount: amount,
            ihbInterestRate: previewRes.data.ihbInterestRate,
            estimatedInterest: (amount * previewRes.data.ihbInterestRate / 100 / 12), // Monthly estimate
            netPayment: previewRes.data.netPayment,
            warnings: previewRes.data.warnings,
          };
          setPreview(previewData);
          setValidationWarnings(previewRes.data.warnings);
          onPreviewUpdate?.(previewData);
        }

        // Validate entities
        const validation = await intercompanyApi.validateEntity(payingEntityId, 'POBO', amount);
        if (!validation.data.valid) {
          setValidationErrors([validation.data.reason || 'Validation failed']);
        } else {
          setValidationErrors([]);
        }
      } catch (error) {
        console.error('Preview failed:', error);
      } finally {
        setPreviewLoading(false);
      }
    };

    if (enabled) {
      generatePreview();
    }
  }, [enabled, payingEntityId, behalfEntityId, amount, currencyCode, onPreviewUpdate]);

  return (
    <Card className={cn('transition-colors', enabled ? 'bg-accent-50 dark:bg-accent-500/10 border-accent-200 dark:border-accent-500/30' : 'bg-neutral-50 dark:bg-primary-950')}>
