            externalLimitAvailable: 60000000,
            internalLimitAvailable: 50000000,
            totalAvailable: 273758500,
            approved: amount <= 50000,
          },
        ].slice(0, amount > 50000 ? 2 : 4),
      };

      setResult(mockResult);
