                      <input
                        type="checkbox"
                        checked={confirmBoardApproval}
                        onChange={(e) => setConfirmBoardApproval(e.target.checked)}
                        className="mt-1 w-4 h-4 text-cat-2 rounded border-neutral-300 dark:border-primary-700 focus:ring-cat-2"
                      />
