  updateStatus: (id: string, status: string, reason?: string) => fetchApi<Program>('/' + id + '/status', { method: 'PATCH', body: JSON.stringify({ status, reason }) }),
  delete: (id: string) => fetchApi<void>('/' + id, { method: 'DELETE' }),
};

