        <div className="flex gap-3 pt-4 border-t border-neutral-200 dark:border-primary-800">
          {hasXml && onViewXml && (
            <Button variant="outline" className="flex-1" leftIcon={<FileCode className="w-4 h-4" />} onClick={onViewXml}>
              View XML
