  poolCode: string;
  description?: string;
  countryCode: string;
  bankCode: string;
  prefix: string;
  suffixLength: number;
  poolSize: number;
  availableCount: number;
  reservedCount: number;
  assignedCount: number;
  utilizationPercent?: number;
  assignmentTtlMinutes: number;
  autoReturnExpired: boolean;
  lowThresholdPercent: number;
  status: 'ACTIVE' | 'INACTIVE' | 'EXHAUSTED';
  createdAt: string;
  updatedAt?: string;
}

interface Viban {
