  vibanType?: string;
  referenceType?: string;
  referenceId?: string;
  expectedAmount?: number;
  remainingAmount?: number;
  currencyCode?: string;
  status: 'ACTIVE' | 'AVAILABLE' | 'RESERVED' | 'EXPIRED' | 'DISABLED';
  isPrimary?: boolean;
  singleUse?: boolean;
  timesUsed?: number;
  totalAmountReceived?: number;
  validFrom?: string;
  validUntil?: string;
  customerName?: string;
  purpose?: string;
