        {vibans.length === 0 && <div className="text-center py-12"><Hash className="w-12 h-12 text-neutral-300 mx-auto mb-3 dark:text-neutral-600" /><p className="text-neutral-500 dark:text-neutral-400">No VIBANs found</p></div>}
      </Card>
    </div>
  );
};

