          hint="Determines default MCC restrictions and expense categories"
        >
          <SelectField
            value={formData.cardProgramType || ''}
            onChange={(v) => updateField('cardProgramType', v)}
            options={CARD_PROGRAM_TYPES.map(t => ({
              value: t.value,
              label: t.label
