/**
 * Hook for bulk operations
 */
export function useVaBulkOperations() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<{
    successCount: number;
    failureCount: number;
    errors: Array<{ accountId: string; error: string }>;
  } | null>(null);

  const bulkUpdateStatus = useCallback(async (
    accountIds: string[],
    status: string,
    reason?: string
  ) => {
    setLoading(true);
    setError(null);
    try {
      const response = await vaApi.bulkUpdateStatus({ accountIds, status, reason });
      setResult({
        successCount: response.successCount,
        failureCount: response.failureCount,
        errors: response.errors || [],
      });
      return response;
    } catch (err: any) {
      setError(err.message || 'Bulk operation failed');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const bulkUpdateLimits = useCallback(async (
    accountIds: string[],
    limits: Omit<import('./vaTypes').BulkLimitsUpdateRequest, 'accountIds'>
  ) => {
    setLoading(true);
    setError(null);
    try {
      const response = await vaApi.bulkUpdateLimits({ accountIds, ...limits });
      setResult({
        successCount: response.successCount,
        failureCount: response.failureCount,
        errors: response.errors || [],
      });
      return response;
    } catch (err: any) {
      setError(err.message || 'Bulk operation failed');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const reset = useCallback(() => {
    setError(null);
    setResult(null);
  }, []);

  return {
    loading,
    error,
    result,
    bulkUpdateStatus,
    bulkUpdateLimits,
    reset,
  };
}

