    setError(null);
    try {
      return await vaApi.resetMonthlyLimits(id);
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, [id]);

  const resetAnnual = useCallback(async () => {
    if (!id) throw new Error('No account ID');
    setLoading(true);
    setError(null);
    try {
      return await vaApi.resetAnnualLimits(id);
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, [id]);

  return {
    loading,
    error,
    resetDaily,
    resetWeekly,
    resetMonthly,
    resetAnnual,
  };
}

